class StructuredLogicalPlanTest {

	private static final ObjectMapper MAPPER = new ObjectMapper();
	private static final SimpleValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	@Test
	void serializesNestedOperatorsAndArgumentsFromTheAlgebra() {
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS, Var.of("s"),
				Var.of("predicate", VALUE_FACTORY.createIRI("urn:test:predicate"), true, true), Var.of("o"),
				Var.of("g"));
		Projection projection = new Projection(new Graph(Var.of("g"), pattern),
				new ProjectionElemList(new ProjectionElem("s", "subject")));
		Slice slice = new Slice(projection, 5, 100);

		JsonNode root = jsonPlan(slice);

		assertThat(root.path("operator").asString()).isEqualTo("Slice");
		assertThat(root.path("type").asString()).isEqualTo(slice.getSignature());
		assertThat(root.at("/arguments/limit").longValue()).isEqualTo(100);
		assertThat(root.at("/arguments/offset").longValue()).isEqualTo(5);
		assertThat(root.at("/plans/0/operator").asString()).isEqualTo("Projection");
		assertThat(root.at("/plans/0/plans/0/plans/0/arguments/name").asString()).isEqualTo("s");
		assertThat(root.at("/plans/0/plans/0/plans/0/arguments/alias").asString()).isEqualTo("subject");

		JsonNode graph = root.at("/plans/0/plans/1");
		assertThat(graph.path("operator").asString()).isEqualTo("Graph");
		assertThat(graph.at("/plans/0/arguments/name").asString()).isEqualTo("g");
		JsonNode patternNode = graph.at("/plans/1");
		assertThat(patternNode.path("operator").asString()).isEqualTo("StatementPattern");
		assertThat(patternNode.at("/arguments/scope").asString()).isEqualTo("NAMED_CONTEXTS");
		JsonNode predicate = patternNode.at("/plans/1");
		assertThat(predicate.path("operator").asString()).isEqualTo("Var");
		assertThat(predicate.at("/arguments/name").asString()).isEqualTo("predicate");
		assertThat(predicate.at("/arguments/anonymous").asBoolean()).isTrue();
		assertThat(predicate.at("/arguments/value/kind").asString()).isEqualTo("iri");
	}

	@Test
	void serializesPathGroupingAndDistinctAggregateArguments() {
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(Var.of("s"), pattern, Var.of("o"), 1);
		Group group = new Group(path, List.of("s"), List.of(new GroupElem("total", new Count(Var.of("o"), true))));

		JsonNode root = jsonPlan(group);

		assertThat(root.path("operator").asString()).isEqualTo("Group");
		assertThat(root.at("/arguments/groupBindingNames/0").asString()).isEqualTo("s");
		assertThat(root.findValuesAsString("operator")).contains("GroupElem", "Count", "ArbitraryLengthPath");
		assertThat(root.findValues("distinct")).singleElement()
				.satisfies(value -> assertThat(value.asBoolean()).isTrue());
		assertThat(root.findValues("minLength")).singleElement()
				.satisfies(value -> assertThat(value.longValue()).isOne());
	}

	@Test
	void serializesLiteralLexicalFormWithoutInterpretingSignaturePunctuation() {
		String label = "comma, quotes \" and )";
		Compare condition = new Compare(Var.of("s"),
				new ValueConstant(VALUE_FACTORY.createLiteral(label, "en")), Compare.CompareOp.NE);
		Filter filter = new Filter(new BindingSetAssignment(), condition);

		JsonNode root = jsonPlan(filter);

		assertThat(root.at("/plans/0/operator").asString()).isEqualTo("Compare");
		assertThat(root.at("/plans/0/arguments/symbol").asString()).isEqualTo("!=");
		JsonNode literal = root.at("/plans/0/plans/1/arguments/value");
		assertThat(literal.path("kind").asString()).isEqualTo("literal");
		assertThat(literal.path("value").asString()).isEqualTo(label);
		assertThat(literal.path("language").asString()).isEqualTo("en");
	}

	@Test
	void serializesKnownValuesRowsAndLeavesLiveRowsUntouched() {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setDeclaredBindingNames(Set.of("value"));
		MapBindingSet binding = new MapBindingSet();
		binding.addBinding("value", VALUE_FACTORY.createBNode("values"));
		assignment.setBindingSets(List.of(binding, EmptyBindingSet.getInstance()));

		JsonNode materialized = jsonPlan(assignment).path("arguments");
		assertThat(materialized.at("/bindingNames/0").asString()).isEqualTo("value");
		assertThat(materialized.at("/rows/0/value/kind").asString()).isEqualTo("bnode");
		assertThat(materialized.at("/rows/1").isObject()).isTrue();
		assertThat(materialized.at("/rows/1").size()).isZero();

		assignment.setBindingSets(() -> {
			throw new AssertionError("Explaining the plan must leave the live source untouched");
		});

		JsonNode live = jsonPlan(assignment).path("arguments");
		assertThat(live.at("/bindingNames/0").asString()).isEqualTo("value");
		assertThat(live.has("rows")).isFalse();
	}

	private static JsonNode jsonPlan(TupleExpr expression) {
		QueryModelTreeToGenericPlanNode converter = new QueryModelTreeToGenericPlanNode(expression, Set.of(),
				Explanation.Level.Unoptimized);
		return MAPPER.readTree(new ExplanationImpl(converter.getGenericPlanNode(), false, expression).toJson());
	}
}
